\label{cor:bm}
  If an automorphism $\pi$ of $\mathcal{D}_{\mathrm{tt}}$ is induced by a Baire measurable function
  $F\colon2^{\omega}\to2^{\omega}$, then $\pi$ is the identity.

\label{thm:wttintro}
  Theorems~\ref{thm:main}, \ref{thm:cts} and~\ref{thm:ad} and
  Corollary~\ref{cor:bm} hold for the wtt-degrees in place of $\mathcal{D}_{\mathrm{tt}}$.

\label{q:rep}
  \begin{enumerate}
  \item Is every automorphism of $\mathcal{D}_{\mathrm{tt}}$ induced on some comeager set by a
    continuous function?
  \item Is every automorphism of $\mathcal{D}_{\mathrm{tt}}$ induced by an arithmetic function, as
    in the theorem of Slaman and Woodin \cite{SW} for the Turing degrees?
  \end{enumerate}

\label{lem:basic}
  Suppose that $F\colon2^{\omega}\to2^{\omega}$ induces an automorphism $\pi$ of
  $\mathcal{D}_{\mathrm{tt}}$. Then for all $A,B\in2^{\omega}$:
  \begin{itemize}
  \item[\textup{(M)}] if $A\le_{\mathrm{tt}} B$ then $F(A)\le_{\mathrm{tt}} F(B)$;
  \item[\textup{(J)}] $F(A\oplus B)\equiv_{\mathrm{tt}} F(A)\oplus F(B)$;
  \item[\textup{(C)}] if $A$ is computable then $F(A)$ is computable;
  \item[\textup{(I)}] if $F(A)\equiv_{\mathrm{tt}} F(B)$ then $A\equiv_{\mathrm{tt}} B$.
  \end{itemize}
  Consequently:
  \begin{itemize}
  \item[\textup{(N)}] $F$ is not constant on any uncountable set; in
    particular $F$ is not constant on any nonempty open set, nor on any set
    which is comeager in a nonempty open set.
  \end{itemize}

\label{prop:inverse}
  Suppose that a continuous function $F$ induces an automorphism $\pi$ of
  $\mathcal{D}_{\mathrm{tt}}$. Then $\pi^{-1}$ is induced by a tt-functional.

\label{lem:E}
  Assume \eqref{eq:data}. Then there are $k\in\omega$, strings $\alpha,\beta$
  of length $k$, tt-functionals $\Phi_{+},\Phi_{-},\Phi_{1/2}$ and a set
  $E\subseteq D^{*}\cap(N_\alpha\times N_\beta)$ such that
  \begin{enumerate}
  \item $E$ is comeager in $N_\alpha\times N_\beta$;
  \item every pair in $E$ satisfies \textup{(R$_{+}$)}, \textup{(R$_{-}$)}\ and \textup{(R$_{1/2}$)}.
  \end{enumerate}

\label{lem:split}
  Assume \eqref{eq:data} and let $\alpha\in2^{<\omega}$. Then there are
  $j\in\omega$, $b,i\in\{0,1\}$, a string $\sigma\supseteq\alpha$ of some
  length $l$, a number $d\ge 1$ and a string $q_1\supseteq\sigma{}^{\frown}(1-i)$ of
  length $l+d$ such that
  \begin{align*}
    F(Z)(j)&=b &&\text{for all }Z\in D\cap N_{\sigma{}^{\frown} i},\\
    F(Z)(j)&=1-b &&\text{for all }Z\in D\cap N_{q_1}.
  \end{align*}

\label{lem:graph}
  Assume \eqref{eq:data}. Then the set
  \[
    R_\pi=\bigl\{(X,A)\in2^{\omega}\times2^{\omega}:\deg_{\mathrm{tt}}(A)=\pi(\deg_{\mathrm{tt}}(X))\bigr\}
  \]
  is Borel.
